#!/bin/bash
# fastdds_udp_only.xml + base.launch.py 배포(src+install) → 전체 정지(job156) → 깨끗한 기동(job240, base 부터)
H=${JETSON_HOST:-172.30.1.8}; SPS=/mnt/c/Users/magma/AppData/Local/Temp/claude/F--6-Indoor-Rover-Rover/82ce61d4-f5f7-4a25-b2e7-1279291348a9/scratchpad
O="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o LogLevel=ERROR -o ConnectTimeout=10"
for f in fastdds_udp_only.xml base.launch.py job156_stop.sh job240_clean.sh job249_nav2only.sh job223_btdeploy.sh job254_s4run.sh job231_drive.sh job314_relay_orphan.sh; do tr -d '\r' < $SPS/$f > /tmp/$f; sshpass -p <PW> scp $O -q /tmp/$f jetson@$H:/tmp/$f || { echo "scp 실패 $f"; exit 1; }; done
sshpass -p <PW> ssh $O jetson@$H 'set -e; D=~/ros2_ws; cp /tmp/fastdds_udp_only.xml $D/src/rover_bringup/config/; cp /tmp/fastdds_udp_only.xml $D/install/rover_bringup/share/rover_bringup/config/; cp /tmp/base.launch.py $D/src/rover_bringup/launch/; cp /tmp/base.launch.py $D/install/rover_bringup/share/rover_bringup/launch/; python3 -c "import xml.etree.ElementTree as E;E.parse(\"$D/install/rover_bringup/share/rover_bringup/config/fastdds_udp_only.xml\")"; echo "XML whitelist: $(grep -c 127.0.0.1 $D/install/rover_bringup/share/rover_bringup/config/fastdds_udp_only.xml)  launch mount: $(grep -c fastdds_udp_only.xml:/ $D/install/rover_bringup/share/rover_bringup/launch/base.launch.py)"; echo "=== 전체 정지 ==="; bash /tmp/job156_stop.sh 2>&1 | grep -aE "잔존|agent|프로세스|완료"'
echo "=== 깨끗한 기동 (base → 보드 리셋 게이트) ==="
timeout 300 sshpass -p <PW> ssh $O jetson@$H "export FASTRTPS_DEFAULT_PROFILES_FILE=\$HOME/ros2_ws/install/rover_bringup/share/rover_bringup/config/fastdds_udp_only.xml; bash /tmp/job240_clean.sh 15" 2>&1 | grep -aE "에이전트|컨테이너|세션|시리얼|보드|무발행|wheel_odom|rover/status|gyro|map->odom|자세|중단|단일" | head -14
